func TestInspectExposeStructuresTextsBySection(t *testing.T) {
	raw := json.RawMessage(`{
		"adTargetingParameters": {
			"obj_baseRent": "380",
			"obj_zipCode": "13437"
		},
		"contact": {
			"callButtonLabel": "Anruf"
		},
		"sections": [
			{
				"type": "TITLE",
				"title": "Schoene Wohnung"
			},
			{
				"type": "ATTRIBUTE_LIST",
				"title": "Kosten",
				"attributes": [
					{
						"type": "TEXT",
						"label": "Gesamtmiete:",
						"text": "471,18 EUR"
					},
					{
						"type": "CHECK",
						"label": "Balkon/Terrasse:"
					},
					{
						"type": "LINK",
						"label": "SCHUFA-BonitaetsCheck:",
						"reference": {
							"type": "URL_LINK",
							"label": "Online anfordern",
							"url": "https://example.com/schufa",
							"target": "WEB"
						}
					}
				]
			},
			{
				"type": "TEXT_AREA",
				"title": "Objektbeschreibung",
				"text": "Erster Absatz.\n\nZweiter Absatz.\nNoch eine Zeile."
			},
			{
				"type": "AD",
				"ad": {
					"label": "Werbung"
				}
			},
			{
				"type": "CONTACT",
				"mailButtonLabel": "Nachricht"
			}
		]
	}`)
	result, err := inspectExposeJSON("123", raw, DataProvenance{Source: "live"}, 1200, 900)
	if err != nil {
		t.Fatalf("inspectExposeJSON returned error: %v", err)
	}
	if result.TextCount != 5 {
		t.Fatalf("TextCount = %d, want 5; texts=%#v", result.TextCount, result.Texts)
	}
	if len(result.Texts) != 3 {
		t.Fatalf("text groups = %d, want 3; texts=%#v", len(result.Texts), result.Texts)
	}
	if got := result.Texts[0].SectionType; got != "TITLE" {
		t.Fatalf("first text group type = %q, want TITLE", got)
	}
	if got := result.Texts[0].Items[0].Value; got != "Schoene Wohnung" {
		t.Fatalf("title value = %q, want Schoene Wohnung", got)
	}
	costs := result.Texts[1]
	if got := costs.Title; got != "Kosten" {
		t.Fatalf("cost group title = %q, want Kosten", got)
	}
	if got := costs.Items[0].Label; got != "Gesamtmiete" {
		t.Fatalf("attribute label = %q, want Gesamtmiete", got)
	}
	if got := costs.Items[0].Value; got != "471,18 EUR" {
		t.Fatalf("attribute value = %q, want 471,18 EUR", got)
	}
	if costs.Items[1].Checked == nil || !*costs.Items[1].Checked {
		t.Fatalf("check item should be checked: %#v", costs.Items[1])
	}
	if got := costs.Items[2].URL; got != "https://example.com/schufa" {
		t.Fatalf("reference URL = %q, want https://example.com/schufa", got)
	}
	body := result.Texts[2].Items[0]
	if got := len(body.Paragraphs); got != 2 {
		t.Fatalf("paragraph count = %d, want 2; paragraphs=%#v", got, body.Paragraphs)
	}
	if got := body.Paragraphs[1]; got != "Zweiter Absatz.\nNoch eine Zeile." {
		t.Fatalf("second paragraph = %q", got)
	}
	for _, item := range flattenExposeTextItems(result.Texts) {
		if item.Value == "380" || item.Value == "13437" || item.Value == "Anruf" || item.Value == "Nachricht" || item.Value == "Werbung" {
			t.Fatalf("technical or ignored text leaked into structured texts: %#v", item)
		}
	}
}

func TestLimitExposeTextGroupsTrimsItemsNotWholeGroups(t *testing.T) {
	groups := []exposeTextGroup{
		{
			SectionIndex: 0,
			SectionType:  "TITLE",
			Path:         "sections.0",
			Items: []exposeTextItem{
				{Kind: "title", Value: "A"},
			},
		},
		{
			SectionIndex: 1,
			SectionType:  "ATTRIBUTE_LIST",
			Path:         "sections.1",
			Items: []exposeTextItem{
				{Kind: "attribute", Label: "One", Value: "1"},
				{Kind: "attribute", Label: "Two", Value: "2"},
			},
		},
	}
	limited := limitExposeTextGroups(groups, 2)
	if got := countExposeTextItems(limited); got != 2 {
		t.Fatalf("limited item count = %d, want 2; groups=%#v", got, limited)
	}
	if len(limited) != 2 {
		t.Fatalf("limited group count = %d, want 2; groups=%#v", len(limited), limited)
	}
	if got := len(limited[1].Items); got != 1 {
		t.Fatalf("second group item count = %d, want 1", got)
	}
	if got := limited[1].Items[0].Label; got != "One" {
		t.Fatalf("kept item label = %q, want One", got)
	}
}

